def backfill_chunk_source_and_catalog(apps, schema_editor):
    """回填新增的来源类型与冗余章节字段。

    - source：material 非空 → material；ppt 非空 → ppt（讲稿片段此前不存在）；
    - catalog：从来源对象拷贝（material.catalog_id 可空=通用资料；ppt.catalog_id 必有）。
    annotate 一次 join 取来源章节避免 N+1；bulk_update 按 500 条分批。
    """
    from django.db.models import F

    KnowledgeChunk = apps.get_model("knowledge", "KnowledgeChunk")
    db_alias = schema_editor.connection.alias
    qs = (
        KnowledgeChunk.objects.using(db_alias)
        .annotate(_mat_catalog=F("material__catalog_id"), _ppt_catalog=F("ppt__catalog_id"))
        .order_by("pk")
    )
    batch = []
    for chunk in qs.iterator(chunk_size=500):
        if chunk.material_id:
            chunk.source = "material"
            chunk.catalog_id = chunk._mat_catalog
        elif chunk.ppt_id:
            chunk.source = "ppt"
            chunk.catalog_id = chunk._ppt_catalog
        batch.append(chunk)
        if len(batch) >= 500:
            KnowledgeChunk.objects.using(db_alias).bulk_update(batch, ["source", "catalog_id"])
            batch = []
    if batch:
        KnowledgeChunk.objects.using(db_alias).bulk_update(batch, ["source", "catalog_id"])


